import{_ as t,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"计算机网络基础教程（第3版）","description":"从分层、寻址和传输理解计算机网络，附版本说明、主题导读与阅读思考。","frontmatter":{"title":"计算机网络基础教程（第3版）","description":"从分层、寻址和传输理解计算机网络，附版本说明、主题导读与阅读思考。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 网络与操作系统","summary":"从分层、寻址和传输理解计算机网络，附版本说明、主题导读与阅读思考。","status":"active","related":[{"title":"网络简介实验手册","link":"/life/personal/books/computing/network-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络互连技术","link":"/life/personal/books/computing/internetworking","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络技术教程","link":"/life/personal/books/computing/network-technology","kind":"书籍导读","scope":"general","audience":"general"},{"title":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"计算机网络原理","link":"/life/personal/books/computing/network-principles","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Linux命令行与shell脚本编程大全（第4版）","link":"/life/personal/books/computing/linux-shell","kind":"书籍导读","scope":"general","audience":"general"}],"prev":false,"next":{"text":"网络简介实验手册","link":"/life/personal/books/computing/network-lab"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"网络简介实验手册","link":"/life/personal/books/computing/network-lab"}},"headers":[],"relativePath":"life/personal/books/computing/network-foundations.md","filePath":"life/personal/books/computing/network-foundations.md"}'),n={name:"life/personal/books/computing/network-foundations.md"};function i(l,e,s,d,p,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="计算机网络基础教程-第3版" tabindex="-1">计算机网络基础教程（第3版） <a class="header-anchor" href="#计算机网络基础教程-第3版" aria-label="Permalink to &quot;计算机网络基础教程（第3版）&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 网络与操作系统</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书在书单中承担网络基础入门的角色，适合希望理解“浏览器发出的请求怎样到达服务器”的读者。学习重点是把协议、设备、地址和数据传输放进同一条路径，逐渐建立定位故障所需的分层思维。</p><p>阅读时可同步画出家庭网络或开发环境的拓扑：终端、交换机、路由器、DNS 服务与目标服务器各在什么位置，数据经过每一跳时又改变了哪些信息。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>版本待确认。</strong> 当前只知道书名与“第3版”，尚无作者、出版社和 ISBN，不能唯一定位同名教材。以下为本站主题导读，不是原书目录，也不表示原书一定按这些主题分章。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>作者仍待实物核对。清华社有吴辰文、李晶编著的《计算机网络基础教程（第3版·微课视频版）》，ISBN 9787302601487，出版于2022年；出版社介绍了吴辰文的网络教学背景。该记录只是可比对候选，不能因都写“第3版”就确认同册，尤其要核对是否带“微课视频版”字样。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合初学网络的学生，以及需要理解 DNS、TCP、网关与交换机关系的应用开发者。可从一次浏览器请求进入；如果目标是设备配置认证，还需配合相应课程实验。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>导读主题</th><th>关注内容与阅读目标</th></tr></thead><tbody><tr><td>网络组成与性能</td><td>区分带宽、吞吐量、时延与丢包；说明为什么带宽充足仍可能响应很慢。</td></tr><tr><td>分层与封装</td><td>对照 TCP/IP 的层次画出报文封装，分清帧、分组和传输层数据。</td></tr><tr><td>物理传输与链路</td><td>理解信号、共享介质、差错检测和以太网帧，明确链路可靠性的范围。</td></tr><tr><td>局域网与交换</td><td>观察 MAC 地址学习与广播，理解交换机如何决定转发端口。</td></tr><tr><td>IP 地址与路由</td><td>练习子网划分和最长前缀匹配，区分直接交付与经网关转发。</td></tr><tr><td>TCP 与 UDP</td><td>比较连接、可靠传输、流量控制和拥塞控制，避免把 UDP 等同于“更快”。</td></tr><tr><td>应用层协议</td><td>将 DNS、HTTP、邮件等协议放回一次真实通信中，分析它们各自解决的问题。</td></tr><tr><td>网络诊断</td><td>用地址、路由、名称解析与抓包证据逐层排查，不从单次 ping 结果推断全链路正常。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>把“连不上”拆成问题，网络知识才开始发挥作用。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>为一次网页访问画出终端、DNS、默认网关与服务器，分别标记名称解析、路由、传输连接和应用响应的证据。这个练习能避免将 ping 成功直接理解为网站可用。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>基础教材适合建立概念体系，单靠阅读难以获得排障手感；在作者和版本未明时，也不能评价本册是否覆盖最新技术。建议每学一层就配一个抓包或状态检查，并说明证据能证明到哪里。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给需要把网络术语放回真实请求的人：先完成一张路径图，再记忆更多协议名称。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li>书名与版次来自本次提供的书单；准确目录需按纸书版权页和目录页核对。</li><li><a href="https://www.rfc-editor.org/rfc/rfc1122" target="_blank" rel="noopener noreferrer">RFC 1122：Internet 主机通信层要求</a>：分层概念的补充参考，并非本书目录来源。</li><li><a href="https://www.wireshark.org/docs/wsug_html_chunked/" target="_blank" rel="noopener noreferrer">Wireshark 用户指南</a>：用于配合学习观察真实报文。</li><li><a href="https://www.tup.com.cn/bookscenter/book_09109101.html" target="_blank" rel="noopener noreferrer">清华社：第3版·微课视频版候选</a>：核对吴辰文、李晶及 ISBN；并未认定与书单实物一致。</li></ul>',26)])])}const k=t(n,[["render",i]]);export{u as __pageData,k as default};
